#include <stdio.h>
#include <string.h>

#define MOD 1000000007

int main() {
    int n, m;
    scanf("%d %d", &n, &m);

    // ranks[i] = rank of team i at current station (0-indexed)
    int ranks[10];
    for (int i = 0; i < n; i++) {
        int r;
        scanf("%d", &r);
        ranks[i] = r - 1; // convert to 0-indexed
    }

    // changes[i] = change in rank for team i
    int changes[10];
    for (int i = 0; i < n; i++) {
        scanf("%d", &changes[i]);
    }

    // dp[mask][last] = number of ways to arrange teams in mask ending with team 'last'
    // at the previous station
    long long dp[1 << 10][10] = {0};

    // Initialize: any single team can be the only one
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }

    // Iterate over all masks
    for (int mask = 1; mask < (1 << n); mask++) {
        int count = __builtin_popcount(mask);
        if (count == 1) continue; // already initialized

        for (int last = 0; last < n; last++) {
            if (!(mask & (1 << last))) continue;
            int prev_mask = mask ^ (1 << last);

            // Try all possible previous teams
            for (int prev = 0; prev < n; prev++) {
                if (!(prev_mask & (1 << prev))) continue;

                // Check if transition is valid
                // At current station, rank[last] and rank[prev] are known
                // At previous station, last had rank = rank[last] - change[last]
                // prev had rank = rank[prev] - change[prev]
                int prev_rank_last = ranks[last] - changes[last];
                int prev_rank_prev = ranks[prev] - changes[prev];

                // Validate that previous ranks are within [0, n-1]
                if (prev_rank_last < 0 || prev_rank_last >= n) continue;
                if (prev_rank_prev < 0 || prev_rank_prev >= n) continue;

                // Check ordering: last must come after prev in previous station
                // (since last is now later in the ordering at current station,
                //  we need to ensure the relative order makes sense)
                // Actually we are constructing previous station order from last to first
                // So prev should have a lower (better) rank than last at previous station
                if (prev_rank_prev >= prev_rank_last) continue;

                // Also need to ensure that all teams in prev_mask have distinct ranks
                // at previous station that are consistent with the current ranks and changes.
                // We'll check this by validating all pairs when we add a new team.

                dp[mask][last] = (dp[mask][last] + dp[prev_mask][prev]) % MOD;
            }
        }
    }

    // Sum all ways to arrange all teams
    long long ans = 0;
    int full_mask = (1 << n) - 1;
    for (int i = 0; i < n; i++) {
        ans = (ans + dp[full_mask][i]) % MOD;
    }

    printf("%lld\n", ans);

    return 0;
}

