int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    long long *a = (long long *)malloc(sizeof(long long) * N);
    for (int i = 0; i < N; i++) {
        long long r, d;
        scanf("%lld %lld", &r, &d);
        a[i] = r + d;  // previous rank must be current rank + displayed change
    }

    qsort(a, N, sizeof(long long), cmp_ll);

    // Valid previous orders exist iff all previous ranks are exactly 1..N.
    // If some value differs, impossible.
    for (int i = 0; i < N; i++) {
        if (a[i] != i + 1) {
            printf("0\n");
            free(a);
            return 0;
        }
    }

    // Since ranks are a permutation of 1..N, the previous order is uniquely determined.
    printf("1\n");

    free(a);
    return 0;
}

