            }
            prevRank[i] = prev;
        }

        // Count how many teams want each previous position
        int[] count = new int[N];
        for (int i = 0; i < N; i++) {
            count[prevRank[i]]++;
        }

        // For each previous position, if more than 1 team wants it -> impossible
        for (int c : count) {
            if (c > 1) {
                System.out.println(0);
                return;
            }
        }

        // Now we have a permutation mapping: current position i+1 -> previous rank prevRank[i]
        // But we must count permutations of previous ordering consistent with changes.
        // Actually, the mapping is fixed: each team has exactly one possible previous rank.
        // So there is exactly 1 ordering if constraints are consistent.
        // However, if a team's change is 0, and another team also maps to same previous rank, impossible already handled.
