#include <bits/stdc++.h>
using namespace std;
const int MOD = 1e9 + 7;

int main(){
    int n;
    cin >> n;
    vector<int> delta(n+1);
    for(int i = 1; i <= n; i++) cin >> delta[i];

    // team at current rank i, previous rank constraint
    // delta[i] > 0: improved, prev_rank > i (worse before)
    // delta[i] < 0: dropped, prev_rank < i
    // delta[i] == 0: prev_rank == i

    // DP over positions 1..n, assign previous ranks
    // dp[mask] = number of ways to assign previous ranks to first popcount(mask) teams
    // where mask indicates which previous-rank slots have been used

    vector<long long> dp(1<<n, 0);
    dp[0] = 1;
    for(int i = 1; i <= n; i++){
        vector<long long> ndp(1<<n, 0);
        for(int mask = 0; mask < (1<<n); mask++){
            if(!dp[mask]) continue;
            // assign previous rank to team i
            for(int j = 1; j <= n; j++){
                if(mask >> (j-1) & 1) continue;
                if(delta[i] > 0 && j <= i) continue;
                if(delta[i] < 0 && j >= i) continue;
                if(delta[i] == 0 && j != i) continue;
                ndp[mask|(1<<(j-1))] = (ndp[mask|(1<<(j-1))] + dp[mask]) % MOD;
            }
        }
        dp = ndp;
    }
    cout << dp[(1<<n)-1] << endl;
}

