#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> rank_now(N), diff(N);
    for (int i = 0; i < N; i++) cin >> rank_now[i];
    for (int i = 0; i < N; i++) cin >> diff[i];

    // rank_now[i]: team id at current position i+1
    // diff for that team: (previous rank) - (current rank)
    // so previous position = current position + diff
    //
    // We need count of possible previous orders consistent with:
    // if a team's previous position is uniquely determined and valid, it must be there.
    // if multiple teams want same previous position or invalid positions appear, impossible.
    //
    // However, ties in passing order at previous relay station can happen among teams
    // whose displayed rank changes are same? No: ranking is a permutation, so each team's
    // previous rank is determined as above. Thus answer is either 0 or 1.
    //
    // But the intended problem is that TV only shows current ranking and "change" relative
    // to previous station, where "change" is displayed as how many places up/down, and if
    // several teams were tied at the previous checkpoint, their internal order could be any.
    // This means previous station order must satisfy:
    // previous rank of team = current rank + diff, but equal values are allowed, forming groups.
    //
    // So compute value p_i = current_rank + diff.
    // Teams with same p_i were tied at previous station, and their order there can be arbitrary.
    // For consistency, p_i must be nondecreasing in current-rank order? Actually previous ranks
    // after sorting by previous order correspond to these p_i values; any equal values can be permuted.
    // Valid iff all p_i are in [1, N] and when sorted by current rank, p_i is nondecreasing and
    // additionally the k-th smallest p_i must satisfy p_i <= k and group structure feasible.
    //
    // More directly: if previous displayed "rank" allows ties, then assigning rank numbers with competition
    // ranking means teams tied for a place share same rank, and next rank skips accordingly.
    // Then in previous order, if a block of size s starts at position L, all teams in it have displayed rank L.
    // Therefore counts of each rank value must match this rule:
    // if cnt[L] = s > 0, then ranks L+1 ... L+s-1 must have cnt=0.
    // Number of possible previous passing orders is product of s! over all blocks.

    vector<int> cnt(N + 2, 0);
    for (int i = 0; i < N; i++) {
        long long p = (long long)(i + 1) + diff[i];
        if (p < 1 || p > N) {
            cout << 0 << '\n';
            return 0;
        }
        cnt[(int)p]++;
    }

    vector<long long> fact(N + 1, 1);
    for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;

    long long ans = 1;
    int pos = 1;
    while (pos <= N) {
        if (cnt[pos] == 0) {
            cout << 0 << '\n';
            return 0;
        }
        int s = cnt[pos];
        ans = ans * fact[s] % MOD;
        for (int x = pos + 1; x <= min(N, pos + s - 1); x++) {
            if (cnt[x] != 0) {
                cout << 0 << '\n';
                return 0;
            }
        }
        pos += s;
    }

    cout << ans % MOD << '\n';
    return 0;
}
